    ev[x["session"]].add(x["event"]); last[x["session"]]=max(last.get(x["session"],0),x["t"])
end=max(x["t"] for x in acc)
fin={s for s in sid if "done" in ev[s] or "engine_abort" in ev[s]}
unf=[s for s in sid if s not in fin]
print("end",round(end,1))
d=[round(end-last[s],1) for s in unf]
print("unfinished:",len(unf),"last-event seconds before end: min",min(d),"p50",sorted(d)[len(d)//2],"max",max(d))
print("unfinished with last event <5s before end:",sum(1 for x in d if x<5))
'

